using RedAI.Application;
using Microsoft.Extensions.Configuration;
namespace RedAI.Infrastructure;
public sealed class LocalAssetStorage(IConfiguration configuration) : IAssetStorage { private readonly string _root = configuration["ASSET_STORAGE_PATH"] ?? Path.Combine(AppContext.BaseDirectory, "assets"); public async Task<StoredAsset> PutAsync(Stream stream, string key, string contentType, CancellationToken ct) { var path = Path.Combine(_root, key.Replace('/', Path.DirectorySeparatorChar)); Directory.CreateDirectory(Path.GetDirectoryName(path)!); await using var output = File.Create(path); await stream.CopyToAsync(output, ct); return new(key, contentType, output.Length, GetPublicUrl(key)); } public Task<Stream> OpenReadAsync(string key, CancellationToken ct) => Task.FromResult<Stream>(File.OpenRead(Path.Combine(_root, key.Replace('/', Path.DirectorySeparatorChar)))); public Task DeleteAsync(string key, CancellationToken ct) { var p = Path.Combine(_root, key.Replace('/', Path.DirectorySeparatorChar)); if (File.Exists(p)) File.Delete(p); return Task.CompletedTask; } public string GetPublicUrl(string key) => $"/assets/{key}"; }
